// Overflow focused tests for the big integer library and the math libraries.
//
// 1. limb boundaries: every operation is checked with values around 2^32, 2^64, 2^96, 2^128,
//    2^160, 2^192, 2^224 and 2^256 (where carries/borrows between 32/64-bit limbs happen)
// 2. the rarely executed "add back" step of the Knuth division (fixtures generated by
//    tests/tools/knuth-search.js)
// 3. the extreme values allowed by Koinos (u64 token amounts) and by the protocol (max
//    liquidity, min/max prices, fee tiers): the results must be identical to the arbitrary
//    precision reference, and every revert must happen exactly where Solidity reverts.
const ref = require("./reference");
const { call, callString, Revert } = require("./harness");
const fixtures = require("./fixtures/knuth-addback.json");

const MAX256 = ref.MAX256;
const U64_MAX = (1n << 64n) - 1n;
const U128_MAX = (1n << 128n) - 1n;
const wrap = (x) => ((x % (1n << 256n)) + (1n << 256n)) % (1n << 256n);

/** runs the reference and the wasm implementation, both must revert or return the same value */
function same(refFn, wasmFn) {
  let expected, refReverted = false;
  try {
    expected = refFn();
  } catch (e) {
    if (!(e instanceof ref.Revert)) throw e;
    refReverted = true;
  }
  let actual, wasmReverted = false;
  try {
    actual = wasmFn();
  } catch (e) {
    if (!(e instanceof Revert)) throw e;
    wasmReverted = true;
  }
  if (refReverted !== wasmReverted) {
    throw new Error(`revert mismatch: reference ${refReverted ? "reverted" : "returned " + expected}, wasm ${wasmReverted ? "reverted" : "returned " + actual}`);
  }
  if (!refReverted && actual !== expected) {
    throw new Error(`value mismatch: reference ${expected}, wasm ${actual}`);
  }
  return refReverted ? undefined : actual;
}

const checked = (x) => {
  if (x < 0n || x > MAX256) throw new ref.Revert();
  return x.toString();
};

// values around every limb boundary
const SPECIAL = [0n, 1n, 2n, 3n];
for (const k of [31, 32, 33, 63, 64, 65, 95, 96, 97, 127, 128, 129, 159, 160, 161, 191, 192, 193, 223, 224, 225, 255]) {
  const p = 1n << BigInt(k);
  SPECIAL.push(p - 1n, p, p + 1n);
}
SPECIAL.push(MAX256 - 1n, MAX256, 0xFFFFFFFFn << 128n, 0x80000000n << 224n, (MAX256 / 3n) * 2n);

describe("limb boundaries", () => {
  test("add / sub / mul (checked and wrapping)", () => {
    for (const a of SPECIAL) {
      for (const b of SPECIAL) {
        same(() => checked(a + b), () => callString("u256Add", a, b));
        same(() => checked(a - b), () => callString("u256Sub", a, b));
        same(() => checked(a * b), () => callString("u256Mul", a, b));
        expect(callString("u256WrappingAdd", a, b)).toEqual(wrap(a + b).toString());
        expect(callString("u256WrappingSub", a, b)).toEqual(wrap(a - b).toString());
        expect(callString("u256WrappingMul", a, b)).toEqual(wrap(a * b).toString());
      }
    }
  });

  test("div / mod / divRoundingUp", () => {
    for (const a of SPECIAL) {
      for (const b of SPECIAL) {
        same(() => { ref.divRoundingUp(a, b); return (a / b).toString(); }, () => callString("u256Div", a, b));
        same(() => { ref.divRoundingUp(a, b); return (a % b).toString(); }, () => callString("u256Mod", a, b));
        same(() => ref.divRoundingUp(a, b).toString(), () => callString("u256DivRoundingUp", a, b));
      }
    }
  });

  test("mulDiv / mulDivRoundingUp", () => {
    for (const a of SPECIAL) {
      for (const b of SPECIAL) {
        for (const d of [1n, 3n, 1n << 64n, (1n << 96n) + 1n, U128_MAX, 1n << 160n, MAX256 - 1n, MAX256, a, b]) {
          same(() => ref.mulDiv(a, b, d).toString(), () => callString("u256MulDiv", a, b, d));
          same(() => ref.mulDivRoundingUp(a, b, d).toString(), () => callString("u256MulDivRoundingUp", a, b, d));
        }
      }
    }
  });

  test("shifts", () => {
    for (const a of SPECIAL) {
      for (const n of [0, 1, 31, 32, 33, 63, 64, 65, 96, 127, 128, 129, 160, 191, 192, 255, 256, 300]) {
        same(() => checked(a << BigInt(n)), () => callString("u256Shl", a, n));
        expect(callString("u256WrappingShl", a, n)).toEqual(wrap(a << BigInt(n)).toString());
        expect(callString("u256Shr", a, n)).toEqual((a >> BigInt(n)).toString());
      }
    }
  });
});

describe("Knuth division add-back step", () => {
  test("div / mod", () => {
    expect(fixtures.div.length).toBeGreaterThan(0);
    for (const [u, v] of fixtures.div.map((c) => c.map(BigInt))) {
      expect(callString("u256Div", u, v)).toEqual((u / v).toString());
      expect(callString("u256Mod", u, v)).toEqual((u % v).toString());
      expect(callString("u256DivRoundingUp", u, v)).toEqual(ref.divRoundingUp(u, v).toString());
    }
  });

  test("mulDiv with 512-bit dividends", () => {
    expect(fixtures.mulDiv.length).toBeGreaterThan(0);
    for (const [a, b, d] of fixtures.mulDiv.map((c) => c.map(BigInt))) {
      same(() => ref.mulDiv(a, b, d).toString(), () => callString("u256MulDiv", a, b, d));
      same(() => ref.mulDivRoundingUp(a, b, d).toString(), () => callString("u256MulDivRoundingUp", a, b, d));
    }
  });
});

describe("Koinos limits", () => {
  // the largest amount of a Koinos token, and amounts around the i64 limit used for swap deltas
  const AMOUNTS = [1n, 100000000n, (1n << 63n) - 1n, U64_MAX];

  // Tick.tickSpacingToMaxLiquidityPerTick for the enabled tick spacings
  const maxLiquidityPerTick = (tickSpacing) => {
    const minTick = Math.trunc(ref.MIN_TICK / tickSpacing) * tickSpacing;
    const maxTick = Math.trunc(ref.MAX_TICK / tickSpacing) * tickSpacing;
    return U128_MAX / BigInt((maxTick - minTick) / tickSpacing + 1);
  };
  const LIQUIDITIES = [1n, 10n ** 15n, maxLiquidityPerTick(1), maxLiquidityPerTick(10), maxLiquidityPerTick(60), maxLiquidityPerTick(200), U128_MAX];

  const TICKS = [ref.MIN_TICK, ref.MIN_TICK + 1, -443636, -200000, -1, 0, 1, 200000, 443636, ref.MAX_TICK - 1, ref.MAX_TICK];
  const PRICES = TICKS.map(ref.getSqrtRatioAtTick).concat([ref.MIN_SQRT_RATIO + 1n, ref.MAX_SQRT_RATIO - 1n]);
  const FEES = [100, 500, 3000, 10000];

  test("SafeCast boundaries", () => {
    expect(callString("toU64", U64_MAX)).toEqual(U64_MAX.toString());
    expect(() => call("toU64", U64_MAX + 1n)).toThrow(Revert);
    expect(callString("addUint128", U128_MAX - 1n, 1n)).toEqual(U128_MAX.toString());
    expect(() => call("addUint128", U128_MAX, 1n)).toThrow(Revert);
  });

  test("getAmount0Delta / getAmount1Delta at every price and liquidity extreme", () => {
    for (const a of PRICES) {
      for (const b of PRICES) {
        for (const l of LIQUIDITIES) {
          for (const up of [true, false]) {
            same(() => ref.getAmount0Delta(a, b, l, up).toString(), () => callString("getAmount0Delta", a, b, l, up));
            same(() => ref.getAmount1Delta(a, b, l, up).toString(), () => callString("getAmount1Delta", a, b, l, up));
          }
        }
      }
    }
  });

  test("getNextSqrtPriceFromInput / Output with u64 amounts", () => {
    for (const p of PRICES) {
      for (const l of LIQUIDITIES) {
        for (const amount of AMOUNTS) {
          for (const zeroForOne of [true, false]) {
            same(() => ref.getNextSqrtPriceFromInput(p, l, amount, zeroForOne).toString(), () => callString("getNextSqrtPriceFromInput", p, l, amount, zeroForOne));
            same(() => ref.getNextSqrtPriceFromOutput(p, l, amount, zeroForOne).toString(), () => callString("getNextSqrtPriceFromOutput", p, l, amount, zeroForOne));
          }
        }
      }
    }
  });

  test("computeSwapStep with u64 amounts, extreme prices and liquidity", () => {
    for (const current of PRICES) {
      for (const target of PRICES) {
        for (const l of LIQUIDITIES) {
          for (const amount of AMOUNTS) {
            for (const signed of [amount, -amount]) {
              for (const fee of FEES) {
                same(
                  () => ref.computeSwapStep(current, target, l, signed, fee).join(","),
                  () => callString("computeSwapStep", current, target, l, signed, fee)
                );
              }
            }
          }
        }
      }
    }
  });

  test("TickMath round trip at every tick of the tick spacings boundaries", () => {
    for (const tick of TICKS) {
      for (const delta of [-2, -1, 0, 1, 2]) {
        const t = tick + delta;
        if (t < ref.MIN_TICK || t > ref.MAX_TICK) {
          expect(() => call("getSqrtRatioAtTick", t)).toThrow(Revert);
          continue;
        }
        const price = ref.getSqrtRatioAtTick(t);
        expect(callString("getSqrtRatioAtTick", t)).toEqual(price.toString());
        if (price < ref.MAX_SQRT_RATIO) expect(call("getTickAtSqrtRatio", price)).toEqual(t);
      }
    }
  });
});

describe("as-bignum audit cases for the other KoinDX big number types", () => {
  test("H-01: SafeCast.addUint128 detects the overflow of the u128Safe.add vector", () => {
    const a = (11834292359786415467n << 64n) | 14578515230910040473n;
    const b = (8690157821842247249n << 64n) | 9202606200622059783n;
    expect(a + b > U128_MAX).toBe(true);
    expect(() => call("addUint128", a, b)).toThrow(Revert);
    expect(callString("addUint128", a, U128_MAX - a)).toEqual(U128_MAX.toString());
  });

  test("i128 add / sub with negative operands (audit.spec.ts) on I256", () => {
    expect(callString("i256Add", 1n, -1n)).toEqual("0");
    expect(callString("i256Add", -2n, -3n)).toEqual("-5");
    expect(callString("i256Sub", 5n, -1n)).toEqual("6");
    expect(callString("i256Sub", -1n, 1n)).toEqual("-2");
    // L-01 (i256.isEmpty): zero is zero whatever the sign of the operands
    expect(callString("i256Sub", -7n, -7n)).toEqual("0");
    expect(callString("i256BytesRoundTrip", 0n)).toEqual("0");
  });
});
